create perfetto table app as select upid, pid from process where name like 'com.bwales.orbit.labb%';
create perfetto table win as select (select min(ts) from sched where dur>0) a, (select max(ts+dur) from sched where dur>0) b;
select 'threads' k, t.name, round(sum(s.dur)/1e6) run_ms, round(100.0*sum(s.dur)/((select b from win)-(select a from win)),1) pct from sched s join thread t using(utid) where t.upid=(select upid from app) group by t.utid order by run_ms desc limit 6;
select 'main' k, count(*) n_doframe, round(max(s.dur)/1e6,1) longest_ms, round(avg(s.dur)/1e6,1) avg_ms from slice s join thread_track tt on s.track_id=tt.id join thread t using(utid) where t.upid=(select upid from app) and t.tid=(select pid from app) and s.depth=0;
select 'skiadraw' k, count(*) n, round(avg(s.dur)/1e6,1) avg_ms, round(max(s.dur)/1e6,1) max_ms from slice s join thread_track tt on s.track_id=tt.id join thread t using(utid) where t.upid=(select upid from app) and s.name='eglSwapBuffers';
select 'js' k, count(*) n, round(max(s.dur)/1e6,1) longest_ms, round(sum(s.dur)/1e6) tot_ms from slice s join thread_track tt on s.track_id=tt.id join thread t using(utid) where t.upid=(select upid from app) and t.name='mqt_v_js' and s.depth=0;
select 'rt' k, count(*) n, round(max(s.dur)/1e6,1) max_ms, round(avg(s.dur)/1e6,1) avg_ms from slice s join thread_track tt on s.track_id=tt.id join thread t using(utid) where t.upid=(select upid from app) and t.name='RenderThread' and s.depth=0;
select 'gpufreq' k, cast(c.value as int) mhz_k, count(*) n from counter c join counter_track t on c.track_id=t.id where t.name='gpufreq' group by 2 order by 2;
select 'gpuutil' k, round(avg(c.value),1) avg_util from counter c join counter_track t on c.track_id=t.id where t.name='gpu_util Frequency';
select 'mainstate' k, s.state, round(sum(s.dur)/1e6) ms from thread_state s join thread t using(utid) where t.upid=(select upid from app) and t.tid=(select pid from app) group by s.state order by ms desc limit 4;
select 'mainslices' k, substr(s.name,1,40) sn, count(*) n, round(avg(s.dur)/1e6,1) avg_ms, round(max(s.dur)/1e6,1) max_ms from slice s join thread_track tt on s.track_id=tt.id join thread t using(utid) where t.upid=(select upid from app) and t.tid=(select pid from app) and s.name in ('animation','eglSwapBuffers','queueBuffer','dequeueBuffer','traversal','Choreographer#doFrame') group by sn;
select 'doframe_pct' k, round(100.0*sum(case when s.dur>8.33e6 then 1 else 0 end)/count(*),1) pct_over_8ms, count(*) n, cast(percentile(s.dur,0.5)/1e5 as int)/10.0 p50, cast(percentile(s.dur,0.9)/1e5 as int)/10.0 p90 from slice s join thread_track tt on s.track_id=tt.id join thread t using(utid) where t.upid=(select upid from app) and t.tid=(select pid from app) and s.name like 'Choreographer#doFrame%';
